pub interface Area {
  fn compute(self) -> Float64;
}

pub type Circle = {
  radius: Float64;
}

impl Area for Circle {
  fn compute(self) -> Float64 {
    return 3.14159 * self.radius * self.radius;
  }
}

fn main() -> Int {
  let c = Circle{ radius: 5.0 };
  let a = c.compute();
  return a as Int;
}
